arguments.command:
python3 -c "
import json
data = json.load(open('agent/trajectory.json'))
steps = data['steps']
for i,s in enumerate(steps):
    msg = s.get('message')
    src = s.get('source')
    if isinstance(msg, dict):
        content = msg.get('content')
    else:
        content = msg
    text = ''
    if isinstance(content, list):
        for c in content:
            if isinstance(c, dict):
                if c.get('type')=='text':
                    text += c.get('text','')[:200] + ' | '
                elif c.get('type')=='tool_use':
                    text += f\"[TOOL:{c.get('name')} {json.dumps(c.get('input'))[:200]}] \"
                elif c.get('type')=='tool_result':
                    cont = c.get('content')
                    if isinstance(cont,list):
                        for cc in cont:
                            if isinstance(cc,dict) and cc.get('type')=='text':
                                text += '[RESULT]'+cc.get('text','')[:150]
    elif isinstance(content,str):
        text = content[:200]
    print(i, src, text[:300])
"

